const TOOL_SPEC_MAP = new Map(TOOL_SPECS.map((tool) => [tool.name, tool]));

// Additive opt-in surface; never insert these dispatchers into TOOL_SPECS.
const DISCOVERY_ENV = "BITWIG_MCP_TOOL_DISCOVERY";
const DISCOVERY_NAMES = new Set(["search_tools", "call_tool", "mcp_search_tools", "mcp_execute_advanced_tool"]);
const DISCOVERY_DEFINITIONS = [
  {
    name: "search_tools",
    description: "Search the currently policy-enabled Bitwig tool catalog without contacting the DAW. Literal terms match name, description or policy. Availability means policy-enabled, not a live connection.",
    inputSchema: {
      type: "object", additionalProperties: false,
      properties: {
        query: { type: "string", maxLength: 200 },
        limit: { type: "integer", minimum: 1, maximum: 20 },
        offset: { type: "integer", minimum: 0, maximum: 10000 },
      },
    },
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
  },
  {
    name: "call_tool",
    description: "Call one named Bitwig tool with its documented arguments. Rechecks write policy and preserves bridge authentication. Can mutate if the target write policy is enabled; never grants human approval. Cannot call generic dispatchers.",
    inputSchema: {
      type: "object", additionalProperties: false, required: ["name"],
      properties: {
        name: { type: "string", minLength: 1, maxLength: 128 },
        arguments: { type: "object" },
      },
    },
    // Conservative even when the current policy enables only reads.
    annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: false, openWorldHint: true },
  },
  {
    name: "mcp_search_tools",
    description: "Historical alias for search_tools. Searches the policy-enabled catalog locally and returns the modern paginated tools/total/nextOffset response. Does not contact Bitwig or Ear.",
    inputSchema: { type: "object", additionalProperties: false, required: ["query"], properties: { query: { type: "string", maxLength: 200 }, limit: { type: "integer", minimum: 1, maximum: 20 }, offset: { type: "integer", minimum: 0, maximum: 10000 } } },
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
  },
  {
    name: "mcp_execute_advanced_tool",
    description: "Historical alias for call_tool with tool_name and arguments. Rechecks target policy and strict input validation; never grants approval or bypasses authentication. All generic-dispatcher recursion is forbidden.",
    inputSchema: { type: "object", additionalProperties: false, required: ["tool_name", "arguments"], properties: { tool_name: { type: "string", minLength: 1, maxLength: 128 }, arguments: { type: "object" } } },
    annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: false, openWorldHint: true },
  },
];
let discoveryValidator;
const discoveryValidators = new WeakMap();

function discoveryEnabled(env) {
  return env[DISCOVERY_ENV] === "1";
}

async function validateDiscoveryInput(schema, value) {
  // SDK dependency already belongs to this package; load only when validation is needed.
  discoveryValidator ??= import("@modelcontextprotocol/sdk/validation/ajv")
    .then(({ AjvJsonSchemaValidator }) => new AjvJsonSchemaValidator());
  const provider = await discoveryValidator;
  let validate = discoveryValidators.get(schema);
  if (!validate) {
    validate = provider.getValidator(schema);
    discoveryValidators.set(schema, validate);
  }
  return validate(value).valid;
}

function snapshotJsonArguments(input) {
  const ancestors = new Set();
  const visit = (value) => {
    if (value === null || typeof value === "string" || typeof value === "boolean") return;
    if (typeof value === "number" && Number.isFinite(value)) return;
    if (typeof value !== "object") throw new Error("Tool arguments must contain only finite JSON values.");
    if (ancestors.has(value)) throw new Error("Tool arguments must not contain cycles.");
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== Array.prototype && prototype !== null) {
      throw new Error("Tool arguments must contain only plain JSON objects and arrays.");
    }
    ancestors.add(value);
    if (Array.isArray(value)) {
      for (let index = 0; index < value.length; index++) {
        if (!Object.hasOwn(value, index)) throw new Error("Tool argument arrays must not contain empty slots.");
      }
    }
    for (const key of Reflect.ownKeys(value)) {
      if (Array.isArray(value) && key === "length") continue;
      if (Array.isArray(value) && (typeof key !== "string" || !/^(0|[1-9][0-9]*)$/.test(key) || Number(key) >= value.length)) {
        throw new Error("Tool argument arrays must not contain named properties.");
      }
      const descriptor = Object.getOwnPropertyDescriptor(value, key);
      if (typeof key !== "string" || !descriptor?.enumerable || !("value" in descriptor)) {
        throw new Error("Tool arguments must contain only enumerable JSON data properties.");
      }
      visit(descriptor.value);
    }
    ancestors.delete(value);
  };
  visit(input);
  // Reject non-JSON values before stringify could silently turn NaN into null or
  // drop an unknown argument. Detach before asynchronous validation to prevent
  // callers from changing validated arguments while the validator loads.
  const encoded = JSON.stringify(input, (_key, value) => {
    if ((typeof value === "number" && !Number.isFinite(value)) ||
        ["undefined", "function", "symbol", "bigint"].includes(typeof value)) {
      throw new Error("Tool arguments must contain only finite JSON values.");
    }
    return value;
  });
  if (encoded === undefined || Buffer.byteLength(encoded, "utf8") > 65536) {
    throw new Error("Tool arguments must fit within 65536 JSON bytes.");
  }
  return JSON.parse(encoded);
}

async function handleDiscoveryCall(name, input, { call, env, earCall }) {
  const fail = (error, message) => serializeToolError({ error, message });
  if (!discoveryEnabled(env)) return fail("tool_unavailable", "Tool discovery is not enabled.");
  // MCP arguments are JSON. Bound and detach them before asynchronous validation.
  let args;
  try {
    args = snapshotJsonArguments(input);
  } catch (error) {
    return fail("invalid_arguments", error.message);
  }
  const definition = DISCOVERY_DEFINITIONS.find((tool) => tool.name === name);
  if (!(await validateDiscoveryInput(definition.inputSchema, args))) {
    return fail("invalid_arguments", "Arguments do not match the dispatcher input schema.");
  }
  if (!discoveryEnabled(env)) return fail("tool_unavailable", "Tool discovery is not enabled.");

  if (name === "search_tools" || name === "mcp_search_tools") {
    const terms = (args.query ?? "").toLowerCase().trim().split(/\s+/).filter(Boolean);
    const matches = TOOL_SPECS.filter((tool) => isPolicyEnabled(tool.policy, env))
      .filter((tool) => {
        const text = `${tool.name} ${tool.description} ${tool.policy}`.toLowerCase();
        return terms.every((term) => text.includes(term));
      });
    const offset = args.offset ?? 0;
    const limit = args.limit ?? 10;
    const tools = matches.slice(offset, offset + limit).map((tool) => ({
      ...buildToolDefinition(tool), policy: tool.policy,
    }));
    return serializeToolResult({
      tools, total: matches.length,
      nextOffset: offset + tools.length < matches.length ? offset + tools.length : null,
    });
  }

  const targetName = name === "mcp_execute_advanced_tool" ? args.tool_name : args.name;
  if (DISCOVERY_NAMES.has(targetName)) {
    return fail("recursive_tool_call", "Generic tools cannot dispatch generic tools.");
  }
  const target = TOOL_SPEC_MAP.get(targetName);
  if (!target) return fail("unknown_tool", "Requested tool is not in the Bitwig registry.");
  if (!isPolicyEnabled(target.policy, env)) return serializeToolError(buildPolicyBlockedError(target));
  const targetArgs = args.arguments ?? {};
  if (!(await validateDiscoveryInput(target.inputSchema, targetArgs))) {
    return fail("invalid_arguments", "Arguments do not match the target tool input schema.");
  }
  if (!discoveryEnabled(env)) return fail("tool_unavailable", "Tool discovery is not enabled.");
  // The canonical dispatcher rechecks current policy after every await above.
  // It also supplies requiresAuthentication and preserves target result/errors.
  return handleToolCall({ params: { name: target.name, arguments: targetArgs } }, { call, env, earCall });
}

function parseEnabledWritePolicies(env = process.env) {
  const allowAllWrites = String(env[ENABLE_WRITES_ENV] ?? "")
    .trim()
    .toLowerCase();

  if (["1", "true", "yes", "on", "all"].includes(allowAllWrites)) {
    return new Set(WRITE_POLICIES);
  }

  return new Set(
    String(env[WRITE_POLICY_ENV] ?? "")
      .split(",")
      .map((policy) => policy.trim().toLowerCase())
      .filter((policy) => WRITE_POLICIES.includes(policy)),
  );
}

function isPolicyEnabled(policy, env = process.env) {
  return policy === "read" || parseEnabledWritePolicies(env).has(policy);
}

function serializeToolResult(result) {
  return {
    content: [
      {
        type: "text",
        text: JSON.stringify(result, null, 2),
      },
    ],
  };
}

function serializeToolError(error) {
  return {
    isError: true,
    content: [
      {
        type: "text",
        text: JSON.stringify(error, null, 2),
      },
    ],
  };
}

function buildPolicyBlockedError(tool) {
  return {
    error: "policy_blocked",
    tool: tool.name,
    policy: tool.policy,
    message: `Tool ${tool.name} requires the ${tool.policy} write policy before it can call Bitwig.`,
    required_config: {
      anyOf: [
        {
          env: WRITE_POLICY_ENV,
          value: tool.policy,
        },
        {
          env: ENABLE_WRITES_ENV,
          value: "1",
        },
      ],
    },
  };
}

function buildToolDefinition(tool) {
  return {
    name: tool.name,
    description: `[policy:${tool.policy}] ${tool.description}`,
    inputSchema: structuredClone(tool.inputSchema),
  };
}

export function getToolDefinitions({ env = process.env } = {}) {
  const definitions = TOOL_SPECS.filter((tool) => isPolicyEnabled(tool.policy, env)).map(
    buildToolDefinition,
  );
  return discoveryEnabled(env)
    ? [...definitions, ...structuredClone(DISCOVERY_DEFINITIONS)]
    : definitions;
}

// Local configuration only: reuse listTools and its policy parser, never the DAW.
export function getMcpDiagnostics({ env = process.env, clientToolNames } = {}) {
  const enabled = parseEnabledWritePolicies(env);
  const exposedTools = getToolDefinitions({ env }).map((tool) => tool.name);
  let clientToolList = { status: "not_checked" };

  if (clientToolNames !== undefined) {
    if (!Array.isArray(clientToolNames) || clientToolNames.length > 512 ||
        Array.from(clientToolNames).some((name) =>
          typeof name !== "string" || name.length === 0 || name.length > 128 ||
          /[\u0000-\u001f\u007f]/.test(name))) {
      const error = new Error("Expected at most 512 nonempty tool names of at most 128 characters, without control characters.");
      error.code = "invalid_client_tool_list";
      throw error;
    }
    const supplied = new Set(clientToolNames);
    const exposed = new Set(exposedTools);
    const missing = exposedTools.filter((name) => !supplied.has(name));
    // Only echo canonical names. Unrecognized client input might contain secrets.
    const known = (name) => TOOL_SPEC_MAP.has(name) || DISCOVERY_NAMES.has(name);
    const noLongerExposed = [...supplied].filter((name) => known(name) && !exposed.has(name)).sort();
    const unrecognizedCount = [...supplied].filter((name) => !known(name)).length;
    const mismatch = missing.length > 0 || noLongerExposed.length > 0 || unrecognizedCount > 0;
    clientToolList = {
      status: mismatch ? "mismatch" : "matches",
      missing,
      no_longer_exposed: noLongerExposed,
      unrecognized_count: unrecognizedCount,
      ...(mismatch ? {
        error: "tool_list_mismatch",
        hint: "The supplied list differs from local configuration: a stale client list/server process or a different server, environment or version may explain it. Compare the same Bitwig server and complete tools/list result before reloading.",
      } : {}),
    };
  }

  return {
    scope: "local-mcp-configuration",
    surface: "bitwig",
    daw_checked: false,
    mode: enabled.size === 0 ? "read-only" : enabled.size === WRITE_POLICIES.length ? "all-writes" : "selective-writes",
    enabled_policies: ["read", ...WRITE_POLICIES.filter((policy) => enabled.has(policy))],
    disabled_policies: WRITE_POLICIES.filter((policy) => !enabled.has(policy)),
    discovery_enabled: discoveryEnabled(env),
    exposed_tools: exposedTools,
    tool_count: exposedTools.length,
    client_tool_list: clientToolList,
    reload_hint: "After changing MCP configuration, restart the MCP server process and reload the client's tool list/session. Reconcile any uncertain mutation before another attempt; never automatically replay a write.",
  };
}

export async function handleToolCall(
  request,
  { call = callBitwig, env = process.env, earCall = callEar } = {},
) {
  try {
    const { name, arguments: input = {} } = request.params;
    let args = input;
    if (DISCOVERY_NAMES.has(name)) return await handleDiscoveryCall(name, args, { call, env, earCall });
    const tool = TOOL_SPEC_MAP.get(name);

    if (!tool) {
      return serializeToolError({
        error: "unknown_tool",
        message: "Requested tool is not in the Bitwig registry.",
      });
    }

    if (!isPolicyEnabled(tool.policy, env)) {
      return serializeToolError(buildPolicyBlockedError(tool));
    }

    if (tool.validateInput) {
      try {
        args = snapshotJsonArguments(args);
      } catch (error) {
        return serializeToolError({ error: "invalid_arguments", message: error.message });
      }
      if (!(await validateDiscoveryInput(tool.inputSchema, args))) {
        return serializeToolError({ error: "invalid_arguments", message: "Arguments do not match the tool input schema." });
      }
      const argumentError = tool.validateArgs?.(args);
      if (argumentError) {
        return serializeToolError({ error: "invalid_arguments", message: argumentError });
      }
      // Policy may be revoked while the validator loads; never dispatch using
      // the earlier decision after an asynchronous boundary.
      if (!isPolicyEnabled(tool.policy, env)) {
        return serializeToolError(buildPolicyBlockedError(tool));
      }
    }

    if (tool.ear) {
      const result = await earCall(name, args, { env, authorize: () => isPolicyEnabled(tool.policy, env) });
      if (!isPolicyEnabled(tool.policy, env)) return serializeToolError(buildPolicyBlockedError(tool));
      return serializeToolResult({ tool: name, policy: tool.policy, result });
    }

    if (tool.execute) {
      return serializeToolResult(await tool.execute({ args, call }));
    }

    const params = tool.mapArgs ? tool.mapArgs(args) : [];
    const result = await call(
      tool.method,
      params,
      { requiresAuthentication: tool.policy !== "read" },
    );

    if (tool.partialResultIsError && result?.status === "partial") {
      return serializeToolError({
        error: "partial_mutation", tool: tool.name, policy: tool.policy,
        method: tool.method, params, result,
        message: "The controller reported a partial or uncertain mutation. Read back the affected clip after synchronization; if recovery requires a controller reload, keep writes blocked until reload and reconciliation; do not automatically replay the batch.",
      });
    }

    if (tool.policy === "read") {
      return serializeToolResult(result);
    }

    return serializeToolResult({
      tool: tool.name,
      policy: tool.policy,
      method: tool.method,
      params,
      result,
    });
  } catch (error) {
    return serializeToolError({
      error: error instanceof EarClientError ? error.code : "tool_call_failed",
      message: error.message,
    });
  }
}

export async function createMcpServer({ env = process.env, call = callBitwig, earCall = callEar } = {}) {
  const [
    { Server },
    { StdioServerTransport },
    { CallToolRequestSchema, ListToolsRequestSchema },
  ] = await Promise.all([
    import("@modelcontextprotocol/sdk/server/index.js"),
    import("@modelcontextprotocol/sdk/server/stdio.js"),
    import("@modelcontextprotocol/sdk/types.js"),
  ]);

  const server = new Server(
    {
      name: "bitwig-mcp-server",
      version: "0.1.0",
    },
    {
      capabilities: {
        tools: {},
      },
    },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: getToolDefinitions({ env }),
  }));
  server.setRequestHandler(CallToolRequestSchema, (request) =>
    handleToolCall(request, { call, env, earCall }),
  );

  return { server, StdioServerTransport };
}

async function runServer() {
  const { server, StdioServerTransport } = await createMcpServer();
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error("Bitwig MCP Server running on stdio");
}

const isMainModule =
  process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isMainModule) {
  runServer().catch(console.error);
}
